B.Or=s(["De-ashi-barai RL","O-goshi RL"],t.s)
B.On=s(['Prinzip \u201eTate"','Prinzip \u201eKami"'],t.s)
B.MA=s(["Nage-waza \u2192 Osae-komi-waza","Befreiung aus Tate","Befreiung aus Kami"],t.s)
B.a2d=new A.cc("Weitere Kampfrichterkommandos/Handzeichen","Zus\xe4tzlich zu den Grundkommandos zeigt der Kampfrichter Ippon, Waza-ari, Shido und Osae-komi jeweils mit einem eigenen Handzeichen an, begleitet vom gesprochenen Kommando.")
B.a2b=new A.cc("Verbote im Judo","Verboten sind u.a. Schl\xe4ge, Tritte, Angriffe auf Augen/Genitalien/Kehle, gef\xe4hrliche Techniken auf Kopf oder Nacken sowie unsportliches Verhalten.")
B.a2l=new A.cc("Osae-komi-Ansage/Dauer",'Der Kampfrichter ruft \u201eOsae-komi", sobald ein g\xfcltiger Haltegriff beginnt. Ununterbrochene Kontrolle \xfcber die volle Haltedauer ergibt Ippon; bei Unterbrechung ruft er \u201eToketa".')
B.a2o=new A.cc("Sono-mama",'\u201eSono-mama" bedeutet \u201ebleib genau so" \u2014 beide K\xe4mpfer erstarren sofort in ihrer Position, z.B. um ein Foul zu kl\xe4ren. Mit \u201eYoshi" geht der Kampf in derselben Position weiter.')
B.ON=s([B.a2d,B.a2b,B.a2l,B.a2o],t.Lu)
