B.a1S=new A.cc("Handzeichen des Kampfrichters","Ippon: Arm einmal gestreckt \xfcber den Kopf. Waza-ari: Arm seitlich auf Schulterh\xf6he. Shido: Arm mit gestrecktem Zeigefinger zur Seite. Osae-komi: Arm nach vorne unten zur Matte.")
B.a1T=new A.cc("Kriterien f\xfcr Ippon/Waza-ari","Ippon: Wurf mit erheblicher Kraft und Geschwindigkeit, gr\xf6\xdftenteils auf den R\xfccken, kontrolliert ausgef\xfchrt. Fehlt eines dieser Kriterien, wird die Technik als Waza-ari bewertet.")
B.Nb=s([B.a1S,B.a1T],t.Lu)
B.KX=new A.fz(7,"Orange",9,B.R,B.LZ,B.Oy,B.Oh,B.Nb,B.R,null)
B.M5=s(["\xdcberschlag (freier Fall)"],t.s)
B.O2=s(["Ko-uchi (Barai/Gari)","O-uchi (Barai/Gari)","Tai-otoshi RL","Tani-otoshi RL"],t.s)
B.M_=s(["Ude-hishigi-juji-gatame RL","Ude-garami RL","Uki-gatame"],t.s)
